contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint collectAmount) public payable {
        // Choose a positive amount to collect.
        require(collectAmount > 0);

        // No setup: caller starts with zero recorded balance.
        (uint unlockBefore, uint balanceBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        require(balanceBefore == 0);

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        (uint unlockAfter, uint balanceAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        assert(balanceAfter == 0);
    }

    receive() external payable {}
}

